const HEX_REGEX = /^0x.*$/;
const ADDRESS_REGEX = /^0x.*$/;
const MAX_UINT32 = 0xffffffff;

const literalWithMetadata = <T extends string | number | boolean>(
  value: T,
  options?: SchemaOptions,
) => withMetadata(z.literal(value), options);

