export const Hex = (options?: SchemaOptions) => {
  const message =
    errorMessage(options) ?? "Must be a valid hex string starting with '0x'";
  return withMetadata(
    z.string({ error: message }).regex(HEX_REGEX, { error: message }),
    { ...options, errorMessage: message },
    // Safe: HEX_REGEX guarantees the string starts with "0x"; Zod can't narrow a regex match to a template literal.
  ) as z.ZodType<`0x${string}`, `0x${string}`>;
};

export type Hex = z.input<ReturnType<typeof Hex>>;

export const Address = (options?: SchemaOptions) => {
  const message =
    errorMessage(options) ??
    "Must be a valid Ethereum address starting with '0x' (e.g., '0xa363219d7C0b8673df17529D469Db9eFF0f35D2A')";
  return withMetadata(
    z.string({ error: message }).regex(ADDRESS_REGEX, { error: message }),
    { ...options, errorMessage: message },
    // Safe: ADDRESS_REGEX guarantees the string starts with "0x"; Zod can't narrow a regex match to a template literal.
  ) as z.ZodType<`0x${string}`, `0x${string}`>;
};

export type Address = z.input<ReturnType<typeof Address>>;

