/**
 * SDK format: bigint (255n)
 * Wire format: "0xff"
 *
 * Used by SDK clients to encode bigint inputs into JSON-RPC hex strings.
 */
export const HexBigInt = (options?: SchemaOptions) =>
  z.codec(Hex(options), z.bigint({ error: "Expected bigint" }).nonnegative(), {
    decode: (value, ctx) => {
      try {
        return hexToBigInt(value);
      } catch (err) {
        ctx.issues.push({
          code: "custom",
          input: value,
          message:
            err instanceof Error
              ? `Invalid HexBigInt hex: ${err.message}`
              : `Invalid HexBigInt hex: ${value}`,
        });
        return z.NEVER;
      }
    },
    encode: (value) => toHex(value),
  });

/**
 * Like HexBigInt, but the SDK side accepts both bigint and hex string.
 * Use when migrating a field from Hex to HexBigInt without breaking existing
 * SDK consumers who already pass a hex string.
 */
export const HexBigIntCompat = (options?: SchemaOptions) =>
  z.codec(
    Hex(options),
    z.union([
      z.bigint({ error: "Expected bigint or hex string" }).nonnegative(),
      Hex(options).refine((value) => isHex(value), {
        error: "Expected bigint or hex string",
      }),
    ]),
    {
      decode: (value, ctx) => {
        try {
          return hexToBigInt(value);
        } catch (err) {
          ctx.issues.push({
            code: "custom",
            input: value,
            message:
              err instanceof Error
                ? `Invalid HexBigInt hex: ${err.message}`
                : `Invalid HexBigInt hex: ${value}`,
          });
          return z.NEVER;
        }
      },
      encode: (value) => (typeof value === "bigint" ? toHex(value) : value),
    },
  );

/**
 * SDK format: number (255)
 * Wire format: "0xff"
 *
 * Used by SDK clients to encode number inputs into JSON-RPC hex strings.
 */
export const HexNumber = (options?: SchemaOptions) =>
  z.codec(
    Hex(options),
    z
      .number({ error: "Expected number" })
      .int()
      .min(0)
      .max(MAX_UINT32, {
        error: `HexNumber encode error: value is out of 32-bit unsigned range [0, ${MAX_UINT32}]`,
      }),
    {
      decode: (value, ctx) => {
        let parsed: number;
        try {
          parsed = hexToNumber(value);
        } catch (err) {
          ctx.issues.push({
            code: "custom",
            input: value,
            message:
              err instanceof Error
                ? `Invalid HexNumber hex: ${err.message}`
                : `Invalid HexNumber hex: ${value}`,
          });
          return z.NEVER;
        }

        if (!Number.isFinite(parsed) || parsed < 0 || parsed > MAX_UINT32) {
          ctx.issues.push({
            code: "custom",
            input: value,
            message: `HexNumber decode error: ${value} is out of 32-bit unsigned range [0, ${MAX_UINT32}]`,
          });
          return z.NEVER;
        }

        return parsed;
      },
      encode: (value) => numberToHex(value),
    },
  );

/**
 * SDK format: "success" | "reverted"
 * Wire format: "0x1" | "0x0"
 */
export const HexStatus = z.codec(
  z.union([
    literalWithMetadata("0x1", { description: "Success" }),
    literalWithMetadata("0x0", { description: "Reverted" }),
  ]),
  z.enum(["success", "reverted"]),
  {
    decode: (value) => (value === "0x1" ? "success" : "reverted"),
    encode: (value) => (value === "success" ? "0x1" : "0x0"),
  },
);

