const TypedDataDomainInput = object({
  chainId: z.union([z.int().min(1), z.bigint().positive()]).optional(),
  name: z.string().optional(),
  salt: Hex().optional(),
  verifyingContract: Address().optional(),
  version: z.string().optional(),
});

const TypedDataDomainWire = object({
  chainId: z.int().min(1).optional(),
  name: z.string().optional(),
  salt: Hex().optional(),
  verifyingContract: Address().optional(),
  version: z.string().optional(),
});

const TypedDataTypes = z
  .record(
    z.string(),
    z.array(
      object({
        name: z.string(),
        type: z.string(),
      }),
    ),
  )
  .meta({
    description: "Mapping from type name to array of field definitions",
  });

const TypedDataMessage = z
  .record(z.string(), z.unknown())
  .meta({ description: "Mapping from field name to value" });

const TypedDataDefinitionInput = object({
  domain: TypedDataDomainInput.optional(),
  types: TypedDataTypes,
  primaryType: z.string(),
  message: TypedDataMessage,
});

const TypedDataDefinitionWire = object({
  domain: TypedDataDomainWire.optional(),
  types: TypedDataTypes,
  primaryType: z.string(),
  message: TypedDataMessage,
});

export const TypedDataDefinition = z.codec(
  TypedDataDefinitionWire,
  TypedDataDefinitionInput,
  {
    decode: (value) => value,
    encode: (value) => {
      const { domain, types, primaryType, message } = value;
      return {
        domain: {
          ...domain,
          chainId:
            typeof domain?.chainId === "bigint"
              ? Number(domain.chainId)
              : domain?.chainId,
        },
        types: Object.assign({}, types, {
          EIP712Domain: getTypesForEIP712Domain({ domain }),
        }),
        primaryType,
        message: JSON.parse(
          JSON.stringify(message, (_, v) =>
            typeof v === "bigint" ? toHex(v) : v,
          ),
        ),
      };
    },
  },
);

export type TypedDataDefinition = z.input<typeof TypedDataDefinition>;

