const SigWithYParitySchema = object(
  {
    r: Hex(),
    s: Hex(),
    yParity: Hex(),
  },
  { description: "r, s, yParity" },
);

const SigWithVSchema = object(
  {
    r: Hex(),
    s: Hex(),
    v: Hex(),
  },
  {
    description: "r, s, v",
  },
);

export const EcdsaSigData = z.union([
  Hex({
    description: "Hex-encoded signature",
  }),
  SigWithYParitySchema,
  SigWithVSchema,
]);

export type EcdsaSigData = z.input<typeof EcdsaSigData>;

export function decodeEcdsaSigData(data: EcdsaSigData): Hex {
  if (typeof data === "string") {
    return data;
  }

  if ("yParity" in data) {
    return serializeSignature({
      ...data,
      yParity: hexToNumber(data.yParity),
    });
  }

  return serializeSignature({ ...data, v: hexToBigInt(data.v) });
}

export function encodeEcdsaSigWithYParity(
  hex: Hex,
): z.output<typeof SigWithYParitySchema> {
  const parsed = parseSignature(hex);
  return {
    r: parsed.r,
    s: parsed.s,
    yParity: numberToHex(parsed.yParity),
  };
}

export function encodeEcdsaSigWithV(hex: Hex): z.output<typeof SigWithVSchema> {
  const parsed = parseSignature(hex);
  return {
    r: parsed.r,
    s: parsed.s,
    v: numberToHex(yParityToV(parsed.yParity)),
  };
}

